function confirmAction(action,member){const name=member.displayName||member.email||'this member';return window.confirm(`${action} ${name}?\n\nThis action will change their LAWAL.UK account access or permissions.`)}
function activityPayload(type,member,from,to,email){const data={type,actorUid:auth.currentUser.uid,actorName:currentMember?.displayName||auth.currentUser.displayName||'Family member',memberUid:member.id||member.uid,memberName:member.displayName||'Unnamed member',from:from||'',to:to||'',createdAt:serverTimestamp()};if(email!==undefined)data.email=email;return data}
