function renderEvents(snapshot){eventsList.replaceChildren();if(snapshot.empty){eventsList.innerHTML='<p class="room-empty">No events posted for this Circle yet.</p>';return}snapshot.forEach(d=>{const data=d.data(),card=document.createElement('article');card.className='event-card';const when=document.createElement('div');when.className='event-when';const date=new Date(data.date+'T00:00:00');when.innerHTML='<strong>'+date.toLocaleDateString([],{day:'2-digit',month:'short'})+'</strong><span>'+data.time+'</span>';const body=document.createElement('div');body.className='event-card-body';const title=document.createElement('h4');title.textContent=data.title;const location=document.createElement('p');location.className='event-location';location.textContent=data.location;const description=document.createElement('p');description.textContent=data.description;const by=document.createElement('small');by.textContent='Posted by '+(data.displayName||'Member');body.append(title,location,description,by);card.append(when,body);if(canDeleteEvent(data)){const del=document.createElement('button');del.type='button';del.className='secondary small event-delete';del.textContent='Delete';del.addEventListener('click',async()=>{if(confirm('Delete this event?'))await deleteDoc(d.ref)});card.append(del)}eventsList.append(card)})}
