let soroMap=null,soroSelfPoint=null,soroSelfMarker=null;let locationUnsubscribe=null,locationExpiryTimer=null,sharedLocationPoints=[],soroMemberMarkers=new Map(),mapMemberProfiles=new Map();
let pinPlacementMode=false,pendingPinPoint=null,pinPreviewMarker=null,pinUnsubscribe=null,pinRoomId=null,pinMarkers=new Map();
const MAP_COLORS={'#e9ad49':'Gold','#ef4444':'Red','#38bdf8':'Blue','#34d399':'Green','#a78bfa':'Purple'};
function mapColor(value){return Object.hasOwn(MAP_COLORS,value)?value:'#e9ad49'}
