let drawMode=false,drawPointerId=null,drawPoints=[],drawPreview=null,drawUnsubscribe=null,drawRoomId=null,drawLayers=new Map();
function clearDrawStroke(){drawPoints=[];drawPreview?.remove();drawPreview=null;if(mapDrawMessage)mapDrawMessage.textContent='Drag on the map to draw a line.'}
function cancelMapDrawing(){drawMode=false;drawPointerId=null;clearDrawStroke();mapDrawForm?.classList.add('hidden');memberMapEl?.classList.remove('drawing-map');if(soroMap){soroMap.dragging.enable();soroMap.touchZoom.enable();soroMap.doubleClickZoom.enable();soroMap.scrollWheelZoom.enable()}}
function stopCircleDrawings(){if(drawUnsubscribe){drawUnsubscribe();drawUnsubscribe=null}drawRoomId=null;cancelMapDrawing();for(const layer of drawLayers.values())layer.remove();drawLayers.clear()}
function drawingPopup(snapshot,roomId){const drawing=snapshot.data(),content=document.createElement('div'),title=document.createElement('strong'),author=document.createElement('small');content.className='soro-pin-details';title.textContent=drawing.title;author.textContent='Drawn by '+(drawing.displayName||'Circle member');content.append(title,author);if(canRemoveCirclePin(drawing,roomId)){const remove=document.createElement('button');remove.type='button';remove.className='secondary small';remove.textContent='Remove drawing';remove.addEventListener('click',async()=>{if(!window.confirm('Remove this drawing from the Circle map?'))return;try{await deleteDoc(doc(db,'circleMapDrawings',roomId,'drawings',snapshot.id))}catch(err){console.error(err);setMapStatus('Could not remove drawing. '+(err.code||''))}});content.append(remove)}return content}
function renderCircleDrawings(snapshot,roomId){const live=new Set();snapshot.forEach(d=>{const drawing=d.data(),points=drawing.points;if(!Array.isArray(points)||points.length<2||points.length>200||!points.every(p=>p&&Number.isFinite(p.lat)&&p.lat>=-90&&p.lat<=90&&Number.isFinite(p.lng)&&p.lng>=-180&&p.lng<=180))return;live.add(d.id);let layer=drawLayers.get(d.id);if(!layer){layer=L.polyline(points.map(p=>[p.lat,p.lng]),{color:mapColor(drawing.color),weight:5,opacity:.95}).addTo(soroMap);drawLayers.set(d.id,layer)}else layer.setLatLngs(points.map(p=>[p.lat,p.lng])).setStyle({color:mapColor(drawing.color)});layer.bindPopup(drawingPopup(d,roomId))});for(const [id,layer] of drawLayers){if(!live.has(id)){layer.remove();drawLayers.delete(id)}}}
function watchCircleDrawings(){const roomId=currentRoom?.id;if(!roomId||!soroMap||drawRoomId===roomId)return;stopCircleDrawings();drawRoomId=roomId;drawUnsubscribe=onSnapshot(collection(db,'circleMapDrawings',roomId,'drawings'),snap=>renderCircleDrawings(snap,roomId),err=>{console.error(err);setMapStatus('Could not load Circle drawings. '+(err.code||''))})}
function mapDrawPointerDown(event){if(!drawMode||event.target.closest?.('.leaflet-control'))return;event.preventDefault();event.stopPropagation();drawPointerId=event.pointerId;memberMapEl.setPointerCapture(event.pointerId);const point=soroMap.mouseEventToLatLng(event);drawPoints=[[point.lat,point.lng]];drawPreview?.remove();drawPreview=L.polyline(drawPoints,{color:mapColor(mapDrawForm.elements.namedItem('color').value),weight:5,opacity:.9}).addTo(soroMap);mapDrawMessage.textContent='Keep dragging to draw your line.'}
function mapDrawPointerMove(event){if(!drawMode||event.pointerId!==drawPointerId)return;event.preventDefault();event.stopPropagation();const point=soroMap.mouseEventToLatLng(event),last=drawPoints.at(-1);if(drawPoints.length>=200)return;if(last&&soroMap.latLngToContainerPoint(last).distanceTo(soroMap.latLngToContainerPoint(point))<4)return;drawPoints.push([point.lat,point.lng]);drawPreview.setLatLngs(drawPoints)}
function mapDrawPointerUp(event){if(!drawMode||event.pointerId!==drawPointerId)return;event.preventDefault();event.stopPropagation();drawPointerId=null;if(memberMapEl.hasPointerCapture(event.pointerId))memberMapEl.releasePointerCapture(event.pointerId);mapDrawMessage.textContent=drawPoints.length>=2?'Line ready. Add a title and save it.':'Drag farther to make a line.'}
function parsePinCoordinates(value){const match=value.trim().match(/^([+-]?(?:\d+(?:\.\d*)?|\.\d+))[,\s]+([+-]?(?:\d+(?:\.\d*)?|\.\d+))$/);if(!match)return null;const lat=Number(match[1]),lng=Number(match[2]);return Number.isFinite(lat)&&lat>=-90&&lat<=90&&Number.isFinite(lng)&&lng>=-180&&lng<=180?{lat,lng}:null}
