function cancelPinPlacement(){pinPlacementMode=false;pendingPinPoint=null;pinPreviewMarker?.remove();pinPreviewMarker=null;mapPinForm?.classList.add('hidden');memberMapEl?.classList.remove('placing-pin');if(mapPinMessage)mapPinMessage.textContent=''}
