function canRemoveCirclePin(pin,roomId){return pin.uid===auth.currentUser?.uid||currentMember?.role==='owner'||(roomId!=='main'&&currentMember?.role==='admin'&&currentRoom?.id===roomId&&currentRoom?.createdBy===auth.currentUser?.uid)}
function pinIcon(color){return L.divIcon({className:'soro-circle-pin-wrap',html:'<span class="soro-circle-pin" style="background-color:'+mapColor(color)+'" aria-hidden="true">◆</span>',iconSize:[32,38],iconAnchor:[16,38]})}
function pinPopup(snapshot,roomId){
  const pin=snapshot.data(),content=document.createElement('div'),title=document.createElement('strong'),note=document.createElement('p'),author=document.createElement('small');
  content.className='soro-pin-details';title.textContent=pin.title;note.textContent=pin.note||'';author.textContent='Pinned by '+(pin.displayName||'Circle member');content.append(title);if(pin.note)content.append(note);content.append(author);
  if(Number.isFinite(pin.latitude)&&pin.latitude>=-90&&pin.latitude<=90&&Number.isFinite(pin.longitude)&&pin.longitude>=-180&&pin.longitude<=180){
    const directions=document.createElement('button');directions.type='button';directions.className='secondary small soro-directions-link';directions.textContent='Directions';
    directions.addEventListener('click',()=>{
      if(!navigator.geolocation||!window.isSecureContext){setMapStatus('Directions need your current GPS location and HTTPS.');return}
      mapDirectionsLink.classList.add('hidden');directions.disabled=true;setMapStatus('Finding your current location for directions…');
      navigator.geolocation.getCurrentPosition(position=>{
        directions.disabled=false;const {latitude,longitude}=position.coords;
        if(!Number.isFinite(latitude)||!Number.isFinite(longitude)){setMapStatus('Could not get a valid GPS location for directions.');return}
        const url='https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(latitude+','+longitude)+'&destination='+encodeURIComponent(pin.latitude+','+pin.longitude);
        mapDirectionsLink.href=url;const opened=window.open(url,'_blank');
        if(opened){opened.opener=null;setMapStatus('Directions opened in a new tab. LAWAL.UK remains here.')}
        else{mapDirectionsLink.classList.remove('hidden');setMapStatus('Tap Open directions above the map to open Google Maps in a new tab.')}
      },error=>{directions.disabled=false;setMapStatus(error.code===1?'Allow location access to get directions from your current position.':'Could not get your current GPS position. Try My Location, then Directions again.')},{enableHighAccuracy:true,maximumAge:0,timeout:20000})
    });content.append(directions)
  }
  if(canRemoveCirclePin(pin,roomId)){
    const edit=document.createElement('button'),remove=document.createElement('button'),form=document.createElement('form'),message=document.createElement('small');edit.type='button';edit.className='secondary small';edit.textContent='Edit pin';form.className='soro-pin-edit hidden';
    const titleLabel=document.createElement('label'),titleInput=document.createElement('input');titleLabel.textContent='Title';titleInput.name='title';titleInput.maxLength=80;titleInput.required=true;titleInput.value=pin.title;titleLabel.append(titleInput);
    const noteLabel=document.createElement('label'),noteInput=document.createElement('textarea');noteLabel.textContent='Note';noteInput.name='note';noteInput.maxLength=240;noteInput.rows=2;noteInput.value=pin.note||'';noteLabel.append(noteInput);
    const colorLabel=document.createElement('label');colorLabel.textContent='Colour';colorLabel.append(mapColorSelect(pin.color));
    const save=document.createElement('button'),cancel=document.createElement('button');save.type='submit';save.className='primary small';save.textContent='Save changes';cancel.type='button';cancel.className='secondary small';cancel.textContent='Cancel';message.setAttribute('role','status');
    cancel.addEventListener('click',()=>form.classList.add('hidden'));edit.addEventListener('click',()=>{form.classList.toggle('hidden');if(!form.classList.contains('hidden'))titleInput.focus()});
    form.addEventListener('submit',async event=>{event.preventDefault();const nextTitle=titleInput.value.trim(),nextNote=noteInput.value.trim();if(!nextTitle){message.textContent='Add a title for this pin.';return}save.disabled=true;message.textContent='Saving…';try{await updateDoc(doc(db,'circleMapPins',roomId,'pins',snapshot.id),{title:nextTitle,note:nextNote,color:mapColor(form.elements.namedItem('color').value)});message.textContent='Pin updated.'}catch(err){console.error(err);message.textContent='Could not update pin. '+(err.code||'')}finally{save.disabled=false}});
    form.append(titleLabel,noteLabel,colorLabel,save,cancel,message);remove.type='button';remove.className='secondary small';remove.textContent='Remove pin';remove.addEventListener('click',async()=>{if(!window.confirm('Remove this pin from the Circle map?'))return;try{await deleteDoc(doc(db,'circleMapPins',roomId,'pins',snapshot.id))}catch(err){console.error(err);setMapStatus('Could not remove pin. '+(err.code||''))}});content.append(edit,remove,form)
  }return content
}
function renderCirclePins(snapshot,roomId){const live=new Set();snapshot.forEach(d=>{const pin=d.data();if(typeof pin.latitude!=='number'||typeof pin.longitude!=='number')return;live.add(d.id);let marker=pinMarkers.get(d.id);if(!marker){marker=L.marker([pin.latitude,pin.longitude],{icon:pinIcon(pin.color)}).addTo(soroMap);pinMarkers.set(d.id,marker)}else marker.setLatLng([pin.latitude,pin.longitude]).setIcon(pinIcon(pin.color));marker.bindPopup(pinPopup(d,roomId))});for(const [id,marker] of pinMarkers){if(!live.has(id)){marker.remove();pinMarkers.delete(id)}}}
