function soroMarkerIcon(point){const profile=mapMemberProfiles.get(point.uid)||{},photo=point.mine&&point.uid.startsWith('local-')?(currentMember?.photoURL||auth.currentUser?.photoURL):profile.photoURL;const avatar=document.createElement('span');avatar.className='soro-leaflet-marker'+(point.mine?' mine':'');if(photo&&/^https:\/\//i.test(photo)){const img=document.createElement('img');img.src=photo;img.alt='';img.referrerPolicy='no-referrer';avatar.append(img)}else avatar.textContent=(profile.displayName||point.displayName||'M').trim().charAt(0).toUpperCase()||'M';return L.divIcon({className:'soro-leaflet-marker-wrap',html:avatar.outerHTML,iconSize:[40,40],iconAnchor:[20,20]})}
