function soroMarkerDetails(point){const profile=mapMemberProfiles.get(point.uid)||{},details=document.createElement('div'),name=document.createElement('strong'),info=document.createElement('p');details.className='soro-marker-details';name.textContent=point.mine?'Your location':profile.displayName||point.displayName||'LAWAL member';info.textContent=point.uid.startsWith('local-')?'Only you can see this location.':'Shared until '+new Date(point.expiresAt).toLocaleString([], {hour:'2-digit',minute:'2-digit',day:'numeric',month:'short'});details.append(name,info);if(Number.isFinite(point.accuracy)){const accuracy=document.createElement('small');accuracy.textContent='GPS accuracy ±'+Math.round(point.accuracy)+' m';details.append(accuracy)}return details}
function ensureSoroMap(){if(soroMap||!memberMapEl||typeof window.L==='undefined')return;soroMap=L.map(memberMapEl,{zoomControl:true,attributionControl:true,zoomAnimation:true,fadeAnimation:true,markerZoomAnimation:true,wheelPxPerZoomLevel:120}).setView([9,15],3);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(soroMap);soroMap.on('click',event=>{if(!pinPlacementMode)return;previewPinPoint(event.latlng);mapPinForm.elements.namedItem('coordinates').value=event.latlng.lat.toFixed(6)+' '+event.latlng.lng.toFixed(6);mapPinMessage.textContent='Place selected. Add a title and save the pin.'});memberMapEl.addEventListener('pointerdown',mapDrawPointerDown,true);memberMapEl.addEventListener('pointermove',mapDrawPointerMove,true);memberMapEl.addEventListener('pointerup',mapDrawPointerUp,true);memberMapEl.addEventListener('pointercancel',mapDrawPointerUp,true);setTimeout(()=>soroMap?.invalidateSize(),0)}
function refreshSoroMapPoints(){if(!soroMap)return;const points=[...sharedLocationPoints];if(soroSelfPoint&&!points.some(p=>p.uid===soroSelfPoint.uid))points.push(soroSelfPoint);const live=new Set(points.map(p=>p.uid));for(const [uid,marker] of soroMemberMarkers){if(!live.has(uid)){marker.remove();soroMemberMarkers.delete(uid)}}for(const p of points){let marker=soroMemberMarkers.get(p.uid);const name=mapMemberProfiles.get(p.uid)?.displayName||p.displayName||'LAWAL member',label=p.mine?'Your location':name;if(!marker){marker=L.marker([p.latitude,p.longitude],{icon:soroMarkerIcon(p),title:label,keyboard:true}).addTo(soroMap);soroMemberMarkers.set(p.uid,marker)}else marker.setLatLng([p.latitude,p.longitude]).setIcon(soroMarkerIcon(p));marker.options.title=label;marker.bindPopup(soroMarkerDetails(p))}}
function hideMapView(){mapView?.classList.add('hidden');sidebarMapButton?.classList.remove('active')}
function showMap(){if(!currentRoom)return;clearReply();stopEvents();messageList.classList.add('hidden');messageForm.classList.add('hidden');replyBar.classList.add('hidden');eventsView.classList.add('hidden');resourcesView.classList.add('hidden');proverbsView.classList.add('hidden');settingsView.classList.add('hidden');currencyView.classList.add('hidden');mapView.classList.remove('hidden');[sidebarCirclesButton,sidebarMembersButton,sidebarEventsButton,sidebarResourcesButton,sidebarSettingsButton].forEach(b=>b?.classList.remove('active'));sidebarMapButton.classList.add('active');ensureSoroMap();watchSharedLocations();watchCirclePins();watchCircleDrawings();loadMapMemberProfiles();setTimeout(()=>soroMap?.invalidateSize(),0)}
function setMapStatus(message){if(mapMessage)mapMessage.textContent=message;else window.alert(message)}
async function locateSelf(){setMapStatus('My Location button pressed…');if(!window.isSecureContext){setMapStatus('Location requires a secure HTTPS connection.');return}if(!navigator.geolocation){setMapStatus('Location is not supported on this device.');return}if(mapMyLocation)mapMyLocation.disabled=true;let permission='unknown';try{if(navigator.permissions?.query){permission=(await navigator.permissions.query({name:'geolocation'})).state}}catch(error){console.warn('LAWAL could not read geolocation permission state',error)}if(permission==='denied'){setMapStatus('Location is blocked for this site. Open Brave site settings for LAWAL.UK, set Location to Allow, reload the page, then try again.');if(mapMyLocation)mapMyLocation.disabled=false;return}setMapStatus(permission==='granted'?'Location permission is allowed. Getting GPS position…':'Waiting for browser location permission…');navigator.geolocation.getCurrentPosition(pos=>{ensureSoroMap();const lat=pos.coords.latitude,lng=pos.coords.longitude;soroSelfPoint={uid:'local-'+(auth.currentUser?.uid||'self'),displayName:'Your current location',latitude:lat,longitude:lng,accuracy:pos.coords.accuracy,mine:true};refreshSoroMapPoints();soroMap?.flyTo([lat,lng],18,{animate:true,duration:3.5});setMapStatus('Location found. Your avatar shows your position. It has not been shared.');if(mapMyLocation)mapMyLocation.disabled=false},err=>{console.error('LAWAL geolocation failed',err);setMapStatus(err.code===1?'Location permission was denied or blocked for this site. Check Brave site settings for LAWAL.UK and allow Location.':err.code===2?'Your device could not determine its location. Check Location/GPS and try again.':err.code===3?'Location request timed out. Check Location/GPS and try again.':'Could not get your location.');if(mapMyLocation)mapMyLocation.disabled=false},{enableHighAccuracy:true,timeout:20000,maximumAge:0})}
function closeMobileNav(){chatLayout?.classList.remove('mobile-nav-open');mobileMenuToggle?.setAttribute('aria-expanded','false');mobileMenuToggle?.setAttribute('aria-label','Open navigation')}
mobileMenuToggle?.addEventListener('click',()=>{const open=chatLayout?.classList.toggle('mobile-nav-open');mobileMenuToggle.setAttribute('aria-expanded',open?'true':'false');mobileMenuToggle.setAttribute('aria-label',open?'Close navigation':'Open navigation')});
document.querySelector('.chat-sidebar-nav')?.addEventListener('click',event=>{if(event.target.closest('button'))closeMobileNav()});
sidebarMapButton?.addEventListener('click',showMap);mapMyLocation?.addEventListener('click',locateSelf);mapShareLocation?.addEventListener('click',()=>{if(activeLocationShare||sharedLocationPoints.some(point=>point.mine)){stopLocationSharing();return}mapSharePanel.classList.remove('hidden');mapMessage.textContent='Choose how long to share your precise location.'});mapShareCancel?.addEventListener('click',()=>{mapSharePanel.classList.add('hidden');mapMessage.textContent=''});
mapAddPin?.addEventListener('click',()=>{cancelMapDrawing();ensureSoroMap();pinPlacementMode=true;pendingPinPoint=null;pinPreviewMarker?.remove();pinPreviewMarker=null;mapPinForm.reset();mapPinForm.classList.remove('hidden');memberMapEl.classList.add('placing-pin');mapPinMessage.textContent='Tap the map or enter coordinates for the pin.';setTimeout(()=>soroMap?.invalidateSize(),0)});
mapPinCancel?.addEventListener('click',cancelPinPlacement);
mapPinForm?.elements.namedItem('coordinates')?.addEventListener('change',event=>{const value=event.target.value.trim();if(!value){pendingPinPoint=null;pinPreviewMarker?.remove();pinPreviewMarker=null;return}const point=parsePinCoordinates(value);if(!point){mapPinMessage.textContent='Enter latitude then longitude, for example 6.807948 3.183538.';return}ensureSoroMap();previewPinPoint(point);soroMap.flyTo(point,Math.max(soroMap.getZoom(),15),{animate:true,duration:1.5});mapPinMessage.textContent='Coordinates selected. Add a title and save the pin.'});

mapPinForm?.addEventListener('submit',async event=>{event.preventDefault();const coordinates=mapPinForm.elements.namedItem('coordinates').value.trim(),point=coordinates?parsePinCoordinates(coordinates):pendingPinPoint;if(!point){mapPinMessage.textContent=coordinates?'Enter valid latitude and longitude (−90 to 90, −180 to 180).':'Tap the map or enter coordinates first.';return}const roomId=currentRoom?.id,user=auth.currentUser;if(!roomId||!user)return;const title=mapPinForm.elements.namedItem('title').value.trim(),note=mapPinForm.elements.namedItem('note').value.trim();if(!title){mapPinMessage.textContent='Add a title for this pin.';return}const submit=mapPinForm.querySelector('[type="submit"]');submit.disabled=true;mapPinMessage.textContent='Saving pin…';try{await addDoc(collection(db,'circleMapPins',roomId,'pins'),{uid:user.uid,displayName:currentMember?.displayName||user.displayName||'Circle member',title,note,color:mapColor(mapPinForm.elements.namedItem('color').value),latitude:point.lat,longitude:point.lng,createdAt:serverTimestamp()});cancelPinPlacement();setMapStatus('Pin added to '+(currentRoom?.name||'this Circle')+'.')}catch(err){console.error(err);mapPinMessage.textContent='Could not save pin. '+(err.code||'')}finally{submit.disabled=false}});
mapDrawButton?.addEventListener('click',()=>{cancelPinPlacement();ensureSoroMap();drawMode=true;clearDrawStroke();mapDrawForm.reset();mapDrawForm.classList.remove('hidden');memberMapEl.classList.add('drawing-map');soroMap.dragging.disable();soroMap.touchZoom.disable();soroMap.doubleClickZoom.disable();soroMap.scrollWheelZoom.disable();setTimeout(()=>soroMap?.invalidateSize(),0)});
mapDrawClear?.addEventListener('click',clearDrawStroke);
mapDrawForm?.elements.namedItem('color')?.addEventListener('change',event=>drawPreview?.setStyle({color:mapColor(event.target.value)}));
mapDrawCancel?.addEventListener('click',cancelMapDrawing);
mapRefresh?.addEventListener('click',async()=>{if(!currentRoom||!soroMap)return;const roomId=currentRoom.id;mapRefresh.disabled=true;setMapStatus('Refreshing map…');soroMap.invalidateSize();soroMap.eachLayer(layer=>{if(layer instanceof L.TileLayer)layer.redraw()});const [locations,pins,drawings]=await Promise.allSettled([getDocs(collection(db,'memberLocations')),getDocs(collection(db,'circleMapPins',roomId,'pins')),getDocs(collection(db,'circleMapDrawings',roomId,'drawings'))]);if(currentRoom?.id===roomId){if(locations.status==='fulfilled')renderSharedLocations(locations.value);if(pins.status==='fulfilled')renderCirclePins(pins.value,roomId);if(drawings.status==='fulfilled')renderCircleDrawings(drawings.value,roomId);await loadMapMemberProfiles();setMapStatus([locations,pins,drawings].every(result=>result.status==='fulfilled')?'Map refreshed.':'Map tiles refreshed, but some Circle data could not be loaded.')}mapRefresh.disabled=false});

mapDrawForm?.addEventListener('submit',async event=>{event.preventDefault();if(drawPoints.length<2){mapDrawMessage.textContent='Draw a line on the map first.';return}const roomId=currentRoom?.id,user=auth.currentUser;if(!roomId||!user)return;const title=mapDrawForm.elements.namedItem('title').value.trim();if(!title){mapDrawMessage.textContent='Add a title for this drawing.';return}const submit=mapDrawForm.querySelector('[type="submit"]');submit.disabled=true;mapDrawMessage.textContent='Saving drawing…';try{await addDoc(collection(db,'circleMapDrawings',roomId,'drawings'),{uid:user.uid,displayName:currentMember?.displayName||user.displayName||'Circle member',title,color:mapColor(mapDrawForm.elements.namedItem('color').value),points:drawPoints.map(([lat,lng])=>({lat,lng})),createdAt:serverTimestamp()});cancelMapDrawing();setMapStatus('Drawing added to '+(currentRoom?.name||'this Circle')+'.')}catch(err){console.error(err);mapDrawMessage.textContent='Could not save drawing. '+(err.code||'')}finally{submit.disabled=false}});
function escapeMapHtml(value){const el=document.createElement('span');el.textContent=String(value??'');return el.innerHTML}
function setShareButtonState(sharing){if(!mapShareLocation)return;mapShareLocation.textContent=sharing?'Stop sharing':'Share Location';mapShareLocation.setAttribute('aria-label',sharing?'Stop sharing your location':'Share your location')}
function renderSharedLocations(snap){if(locationExpiryTimer)clearTimeout(locationExpiryTimer);const now=Date.now();let nextExpiry=Infinity;sharedLocationPoints=[];snap.forEach(d=>{const x=d.data(),expiry=x.expiresAt?.toMillis?.()||0;if(expiry<=now||typeof x.latitude!=='number'||typeof x.longitude!=='number')return;nextExpiry=Math.min(nextExpiry,expiry);sharedLocationPoints.push({uid:d.id,displayName:x.displayName||'LAWAL member',latitude:x.latitude,longitude:x.longitude,accuracy:typeof x.accuracy==='number'?x.accuracy:null,expiresAt:expiry,mine:d.id===auth.currentUser?.uid})});refreshSoroMapPoints();const mine=snap.docs.find(d=>d.id===auth.currentUser?.uid&&((d.data().expiresAt?.toMillis?.()||0)>now));setShareButtonState(Boolean(mine||activeLocationShare));if(nextExpiry!==Infinity)locationExpiryTimer=setTimeout(()=>renderSharedLocations(snap),Math.max(1,nextExpiry-now+50))}
function stopLocationFeed(){if(locationUnsubscribe){locationUnsubscribe();locationUnsubscribe=null}if(locationExpiryTimer){clearTimeout(locationExpiryTimer);locationExpiryTimer=null}sharedLocationPoints=[];soroSelfPoint=null;refreshSoroMapPoints();setShareButtonState(false)}
function watchSharedLocations(){if(locationUnsubscribe||!auth.currentUser)return;locationUnsubscribe=onSnapshot(collection(db,'memberLocations'),renderSharedLocations,()=>{mapMessage.textContent='Could not load shared member locations.'})}
let activeLocationShare=null;
function endLocationWatch(){const share=activeLocationShare;if(!share)return;activeLocationShare=null;if(share.watchId!==null)navigator.geolocation.clearWatch(share.watchId);if(share.timer)clearTimeout(share.timer);return share}
function shareLocation(minutes){if(!window.isSecureContext||!navigator.geolocation){mapMessage.textContent='Location requires GPS and a secure HTTPS connection.';return}const user=auth.currentUser;if(!user)return;endLocationWatch();const share={uid:user.uid,watchId:null,timer:null,expiresAt:null,lastWrite:0,saving:false};activeLocationShare=share;setShareButtonState(true);mapSharePanel.classList.add('hidden');mapMessage.textContent='Waiting for your GPS position…';share.watchId=navigator.geolocation.watchPosition(async pos=>{if(activeLocationShare!==share||auth.currentUser?.uid!==share.uid)return;const now=Date.now();if(!share.expiresAt){share.expiresAt=new Date(now+minutes*60000);share.timer=setTimeout(()=>stopLocationSharing(true),minutes*60000)}if(now>=share.expiresAt.getTime()){stopLocationSharing(true);return}if(share.saving||now-share.lastWrite<15000)return;share.saving=true;try{await (share.pendingWrite=setDoc(doc(db,'memberLocations',share.uid),{uid:share.uid,displayName:currentMember?.displayName||user.displayName||'Member',latitude:pos.coords.latitude,longitude:pos.coords.longitude,accuracy:pos.coords.accuracy,expiresAt:share.expiresAt,updatedAt:serverTimestamp()}));if(activeLocationShare!==share)return;share.lastWrite=Date.now();mapSharePanel.classList.add('hidden');setShareButtonState(true);mapMessage.textContent='Live location sharing until '+share.expiresAt.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})+'. Keep this page open for updates.';if(!share.started){share.started=true;ensureSoroMap();soroMap?.flyTo([pos.coords.latitude,pos.coords.longitude],18,{animate:true,duration:3.5})}}catch(err){console.error(err);if(activeLocationShare===share){mapMessage.textContent='Could not update shared location. '+(err.code||'');endLocationWatch();setShareButtonState(sharedLocationPoints.some(point=>point.mine))}}finally{share.saving=false}},err=>{if(activeLocationShare!==share)return;console.error('LAWAL live location failed',err);if(err.code===1){endLocationWatch();setShareButtonState(sharedLocationPoints.some(point=>point.mine));mapMessage.textContent='Location permission was denied. Stop sharing to remove the last position.'}else mapMessage.textContent='Waiting for GPS. Your last shared position remains until sharing ends.'},{enableHighAccuracy:true,timeout:20000,maximumAge:0})}
async function stopLocationSharing(expired=false){const share=endLocationWatch();mapSharePanel.classList.add('hidden');const user=auth.currentUser;if(!user){setShareButtonState(false);return}mapShareLocation.disabled=true;try{if(share?.pendingWrite)await share.pendingWrite.catch(()=>{});await deleteDoc(doc(db,'memberLocations',user.uid));setShareButtonState(false);mapMessage.textContent=expired===true?'Location sharing ended.':'Location sharing stopped.'}catch(err){console.error(err);setShareButtonState(sharedLocationPoints.some(point=>point.mine));mapMessage.textContent='Could not stop sharing. '+(err.code||'')}finally{mapShareLocation.disabled=false}}
document.querySelectorAll('[data-map-duration]').forEach(b=>b.addEventListener('click',()=>shareLocation(Number(b.dataset.mapDuration))));
